insert into public.questions (id,subject,topic,origin,source_label,year,stem,options,answer,explanation,difficulty,book,review_status,is_active) values ('FP-0201','Raciocínio Lógico-Matemático','Porcentagem','autoral','Autoral · Foco PMMG 2027',2026,'Uma mensalidade custava R$ 30,00 e sofreu aumento de 10%. Qual é o novo valor, em reais?','["33", "27", "3", "40"]'::jsonb,0,'Valor após o reajuste: 30 × (1 + 10/100) = R$ 33.','Difícil',null,'revisao_editorial',true) on conflict(id) do update set stem=excluded.stem,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,review_status=excluded.review_status;
insert into public.questions (id,subject,topic,origin,source_label,year,stem,options,answer,explanation,difficulty,book,review_status,is_active) values ('FP-0202','Raciocínio Lógico-Matemático','Razões e proporções','autoral','Autoral · Foco PMMG 2027',2026,'Uma viatura percorre 12 km em 6 minutos, em velocidade constante. Quantos quilômetros percorrerá em 18 minutos?','["24", "18", "36", "48"]'::jsonb,2,'Pela proporcionalidade direta, o tempo triplica e a distância também: 12 × 3 = 36.','Fácil',null,'revisao_editorial',true) on conflict(id) do update set stem=excluded.stem,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,review_status=excluded.review_status;
insert into public.questions (id,subject,topic,origin,source_label,year,stem,options,answer,explanation,difficulty,book,review_status,is_active) values ('FP-0203','Raciocínio Lógico-Matemático','Média aritmética','autoral','Autoral · Foco PMMG 2027',2026,'Qual é a média aritmética dos números pares de 2 até 12, inclusive?','["12", "7", "6", "8"]'::jsonb,1,'A soma dos extremos é 14; a média da progressão é (2 + 12)/2 = 7.','Média',null,'revisao_editorial',true) on conflict(id) do update set stem=excluded.stem,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,review_status=excluded.review_status;
insert into public.questions (id,subject,topic,origin,source_label,year,stem,options,answer,explanation,difficulty,book,review_status,is_active) values ('FP-0204','Raciocínio Lógico-Matemático','Geometria plana','autoral','Autoral · Foco PMMG 2027',2026,'Qual é a área de um retângulo com 7 m de base e 4 m de altura?','["22", "35", "28", "14"]'::jsonb,2,'Área do retângulo = base × altura = 7 × 4 = 28 m².','Difícil',null,'revisao_editorial',true) on conflict(id) do update set stem=excluded.stem,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,review_status=excluded.review_status;
insert into public.questions (id,subject,topic,origin,source_label,year,stem,options,answer,explanation,difficulty,book,review_status,is_active) values ('FP-0205','Raciocínio Lógico-Matemático','Probabilidade','autoral','Autoral · Foco PMMG 2027',2026,'Uma caixa contém 3 bolas azuis e 4 vermelhas. Retira-se uma bola ao acaso. Qual é a probabilidade de ela ser azul?','["3/7", "3/4", "7/3", "4/7"]'::jsonb,0,'Casos favoráveis: 3. Total: 7. Probabilidade: 3/7.','Fácil',null,'revisao_editorial',true) on conflict(id) do update set stem=excluded.stem,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,review_status=excluded.review_status;
insert into public.questions (id,subject,topic,origin,source_label,year,stem,options,answer,explanation,difficulty,book,review_status,is_active) values ('FP-0206','Raciocínio Lógico-Matemático','Equação do 1º grau','autoral','Autoral · Foco PMMG 2027',2026,'Qual é o valor de x na equação 3x + 6 = 27?','["7", "8", "5", "10"]'::jsonb,0,'Subtraindo 6, fica 3x = 21; logo x = 7.','Média',null,'revisao_editorial',true) on conflict(id) do update set stem=excluded.stem,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,review_status=excluded.review_status;
insert into public.questions (id,subject,topic,origin,source_label,year,stem,options,answer,explanation,difficulty,book,review_status,is_active) values ('FP-0207','Raciocínio Lógico-Matemático','Lógica proposicional','autoral','Autoral · Foco PMMG 2027',2026,'Considere P verdadeira e Q falsa. Qual o valor lógico de “P e Q”?','["Depende da ordem", "Falso", "Verdadeiro", "Indeterminado"]'::jsonb,1,'P=True, Q=False. Pela tabela-verdade do conectivo “P e Q”, o resultado é falso.','Difícil',null,'revisao_editorial',true) on conflict(id) do update set stem=excluded.stem,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,review_status=excluded.review_status;
